{
  "name": "QuTech 中央控制器（CC）",
  "name_en": "QuTech Central Controller (CC)",
  "manufacturer": "QuTech",
  "description": "用于量子实验控制的中央时序与序列控制器，可运行硬件序列程序并通过数字接口模块（如 CCIO）分发/同步触发与数字控制信号；支持对数字 I/O 时序链路进行校准、延时调整与状态监测，常用于超导量子比特等实验系统的确定性时序控制与联机诊断。",
  "description_en": "A central timing and sequencing controller for quantum experiments. It runs hardware sequence programs and coordinates synchronized triggers and digital control via digital I/O modules (e.g., CCIO). It supports digital I/O link calibration, delay tuning, and status monitoring, commonly used for deterministic timing control and diagnostics in setups such as superconducting qubit experiments.",
  "tag_hints": [
    "quantum experiment control",
    "hardware sequencer",
    "digital I/O timing",
    "synchronized trigger distribution",
    "DIO calibration",
    "SCPI instrument control",
    "QuTech Central Controller",
    "latency/delay adjustment"
  ],
  "actions": [
    {
      "action_name": "auto-assemble",
      "description": "汇编序列程序字符串。",
      "description_en": "Assemble a sequence program string."
    },
    {
      "action_name": "auto-assemble_and_start",
      "description": "汇编序列程序并启动序列器运行。",
      "description_en": "Assemble the sequence program and start the sequencers."
    },
    {
      "action_name": "auto-calibrate_dio",
      "description": "对指定 CCIO 的数字 I/O 进行校准（基于期望比特模式）。",
      "description_en": "Calibrate digital I/O for a specified CCIO (using an expected bit pattern)."
    },
    {
      "action_name": "auto-debug_get_ccio_reg",
      "description": "读取指定 CCIO 的调试寄存器值。",
      "description_en": "Read a specified CCIO debug register value."
    },
    {
      "action_name": "auto-debug_get_ccio_trace",
      "description": "获取指定 CCIO 的调试跟踪数据。",
      "description_en": "Get debug trace data from a specified CCIO."
    },
    {
      "action_name": "auto-debug_get_traces",
      "description": "按 CCIO 掩码批量获取调试跟踪数据。",
      "description_en": "Get debug traces in bulk using a CCIO mask."
    },
    {
      "action_name": "auto-debug_marker_in",
      "description": "将调试标记接入到指定 CCIO 的输入位。",
      "description_en": "Route a debug marker to a specified CCIO input bit."
    },
    {
      "action_name": "auto-debug_marker_off",
      "description": "关闭指定 CCIO 的调试标记功能。",
      "description_en": "Turn off the debug marker function for a specified CCIO."
    },
    {
      "action_name": "auto-debug_marker_out",
      "description": "将调试标记接入到指定 CCIO 的输出位。",
      "description_en": "Route a debug marker to a specified CCIO output bit."
    },
    {
      "action_name": "auto-debug_set_ccio_trace_on",
      "description": "打开指定 CCIO 的跟踪采集（选择跟踪单元索引）。",
      "description_en": "Enable trace capture on a specified CCIO (selecting a trace unit index)."
    },
    {
      "action_name": "auto-print_status_operation",
