      "description_en": "Read and print the Operation status information (combined CC core and CCIO)."
    },
    {
      "action_name": "auto-print_status_questionable",
      "description": "读取并打印设备可疑（Questionable）状态信息（组合 CC core 与 CCIO）。",
      "description_en": "Read and print the Questionable status information (combined CC core and CCIO)."
    },
    {
      "action_name": "auto-sequence_program_assemble",
      "description": "set 序列程序（上传并汇编序列程序字符串）。",
      "description_en": "set the sequence program (upload and assemble the program string)."
    },
    {
      "action_name": "auto-set_q1_reg",
      "description": "set Q1 寄存器值（仅在 CC 停止时允许）。",
      "description_en": "set a Q1 register value (only allowed when the CC is stopped)."
    },
    {
      "action_name": "auto-set_seqbar_cnt",
      "description": "设置指定 CCIO 的序列屏障/计数器值（无需停止 CC）。",
      "description_en": "Set a sequence barrier/counter value for a specified CCIO (no need to stop the CC)."
    },
    {
      "action_name": "auto-set_status_operation_run_enable",
      "description": "set 运行（Operation:RUN）状态上报使能。",
      "description_en": "set the enable for Operation:RUN status reporting."
    },
    {
      "action_name": "auto-set_status_questionable_bplink_enable",
